package ama.transcript;
import ama.meeting.WorkspaceReadBudget;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.jdbc.core.*;
/** SQL/metadata protocol unit evidence; no actual MySQL plan, access grant or producer proof. */
class Task12WorkspaceTaskScanTest {
 static final String M="00000000-0000-4000-8000-000000000001",T="00000000-0000-4000-8000-000000000002",I="00000000-0000-4000-8000-000000000003";
 @Test void cursorIsCanonicalMicrosecondPosition(){var p=new WorkspaceTaskScan.Position(LocalDateTime.of(2026,10,27,0,0,0,123456000),T);assertEquals(p,WorkspaceTaskScan.Position.parse(p.encode()));for(String value:List.of("2026-10-27T00:00:00.1234567|"+T,"2026-02-30T00:00:00.000000|"+T,"2026-10-27T00:00:00|"+T))assertThrows(IllegalArgumentException.class,()->WorkspaceTaskScan.Position.parse(value));}
 @Test void queryUsesExistingSubjectHistoryAndAdvancesOverEveryFamily(){var p=new WorkspaceTaskScan.Position(LocalDateTime.of(2026,10,27,0,0),T);var query=WorkspaceTaskScan.query(M,20,p);assertTrue(query.sql().contains("FORCE INDEX (task_subject_history)"));assertTrue(query.sql().contains("subject_kind='MEETING' AND subject_id=?"));assertTrue(query.sql().endsWith("ORDER BY created_at DESC,id DESC LIMIT ?"));assertFalse(query.sql().contains("task_type=?"));assertFalse(query.sql().contains("last_error"));assertFalse(query.sql().contains("SELECT *"));assertEquals(List.of(M,p.created(),p.created(),T,21),query.args());}
 @Test void cumulativeBudgetIsReservedBeforeJdbcAcquiresMetadata(){var jdbc=mock(JdbcTemplate.class);var budget=new WorkspaceReadBudget(new WorkspaceReadBudget.Limits(100,100,100,100,1,1,Duration.ofSeconds(5)),()->false);assertThrows(WorkspaceReadBudget.Unavailable.class,()->new WorkspaceTaskScan(jdbc).discover(M,50,null,budget));verifyNoInteractions(jdbc);}
 @Test void taskShapeRejectsUnregisteredFamilyAndMismatchedPoolInput(){var row=WorkspaceTaskScan.metadata(T,"TRANSCRIPT_IMPORT_V1","TRANSCRIPT_IMPORT","MEETING",M,"a".repeat(64),"TRANSCRIPTION_INPUT",I,"b".repeat(64),7,0,0,3,"RUNNING",1,LocalDateTime.of(2026,10,27,0,0));assertEquals(T,row.id());assertEquals("TRANSCRIPT_IMPORT_V1",row.spec().type());assertThrows(WorkspaceReadBudget.Unavailable.class,()->WorkspaceTaskScan.metadata(T,"UNKNOWN","TRANSCRIPT_IMPORT","MEETING",M,"a".repeat(64),"TRANSCRIPTION_INPUT",I,"b".repeat(64),7,0,0,3,"RUNNING",1,LocalDateTime.of(2026,10,27,0,0)));assertThrows(WorkspaceReadBudget.Unavailable.class,()->WorkspaceTaskScan.metadata(T,"MINUTES_GENERATE_V1","TRANSCRIPT_IMPORT","MEETING",M,"a".repeat(64),"GENERATION_INPUT",I,"b".repeat(64),7,0,0,3,"RUNNING",1,LocalDateTime.of(2026,10,27,0,0)));}

 // Real JdbcTemplate executes against JDBC metadata doubles; this is not MySQL qualification.
 private List<WorkspaceTaskScan.Metadata> readRows(List<Map<String,Object>> rows,int limit,WorkspaceTaskScan.Position after,WorkspaceReadBudget budget)throws Exception{
  var ds=mock(javax.sql.DataSource.class);var connection=mock(java.sql.Connection.class);when(ds.getConnection()).thenReturn(connection);
  var statement=mock(java.sql.PreparedStatement.class);when(connection.prepareStatement(anyString())).thenReturn(statement);when(statement.getConnection()).thenReturn(connection);
  var result=mock(java.sql.ResultSet.class);when(statement.executeQuery()).thenReturn(result);var index=new java.util.concurrent.atomic.AtomicInteger(-1);var wasNull=new java.util.concurrent.atomic.AtomicBoolean();
  when(result.next()).thenAnswer(x->index.incrementAndGet()<rows.size());when(result.wasNull()).thenAnswer(x->wasNull.get());
  when(result.getString(anyString())).thenAnswer(x->(String)rows.get(index.get()).get(x.getArgument(0)));
  when(result.getLong(anyString())).thenAnswer(x->{var v=rows.get(index.get()).get(x.getArgument(0));wasNull.set(v==null);return v==null?0:((Number)v).longValue();});
  when(result.getObject(anyString(),eq(LocalDateTime.class))).thenAnswer(x->rows.get(index.get()).get(x.getArgument(0)));
  return new WorkspaceTaskScan(new JdbcTemplate(ds)).discover(M,limit,after,budget);
 }
 private Map<String,Object> task(String id){var row=new HashMap<String,Object>();row.put("id",id);row.put("task_type","TRANSCRIPT_IMPORT_V1");row.put("pool","TRANSCRIPT_IMPORT");row.put("subject_kind","MEETING");row.put("subject_id",M);row.put("producer_key","a".repeat(64));row.put("input_kind","TRANSCRIPTION_INPUT");row.put("input_id",I);row.put("input_fingerprint","b".repeat(64));row.put("business_version",9007199254740993L);row.put("priority",0);row.put("cancel_epoch",0L);row.put("max_attempts",3L);row.put("state","RUNNING");row.put("attempt",1L);row.put("created_at",LocalDateTime.of(2026,10,27,0,0));return row;}
 @Test void jdbcPreservesLargeCountersAndReturnsBoundedLookahead()throws Exception{var budget=new WorkspaceReadBudget();var rows=readRows(List.of(task(I),task(T)),1,null,budget);assertEquals(2,rows.size());assertEquals(9007199254740993L,rows.getFirst().spec().businessVersion());assertEquals(2,budget.usage().rows());assertTrue(budget.usage().bytes()>=2L*4096*4);}
 @Test void jdbcRejectsNullCountersCrossMeetingAndNonAdvancingPages()throws Exception{
  var row=task(T);row.put("business_version",null);assertThrows(WorkspaceReadBudget.Unavailable.class,()->readRows(List.of(row),1,null,new WorkspaceReadBudget()));row.put("business_version",1L);row.put("subject_id",I);assertThrows(WorkspaceReadBudget.Unavailable.class,()->readRows(List.of(row),1,null,new WorkspaceReadBudget()));row.put("subject_id",M);
  assertThrows(WorkspaceReadBudget.Unavailable.class,()->readRows(List.of(row,row),2,null,new WorkspaceReadBudget()));assertThrows(WorkspaceReadBudget.Unavailable.class,()->readRows(List.of(row),1,new WorkspaceTaskScan.Position((LocalDateTime)row.get("created_at"),T),new WorkspaceReadBudget()));assertThrows(WorkspaceReadBudget.Unavailable.class,()->readRows(List.of(task(I),task(T),task(M)),1,null,new WorkspaceReadBudget()));
 }
 @Test void jdbcRejectsUnknownFamiliesEvenInLookahead()throws Exception{var unknown=task(T);unknown.put("task_type","UNKNOWN");assertThrows(WorkspaceReadBudget.Unavailable.class,()->readRows(List.of(task(I),unknown),1,null,new WorkspaceReadBudget()));}
}
